What is the output of this C++ polymorphism example?

```cpp
#include <iostream>
using namespace std;

class Base {
public:
    virtual void show() { cout << "Base "; }
    void print() { cout << "BasePrint "; }
};

class Derived : public Base {
public:
    void show() override { cout << "Derived "; }
    void print() { cout << "DerivedPrint "; }
};

int main() {
    Base *b = new Derived();
    b->show();
    b->print();
    return 0;
}
```

